% Reglas

adivinar :-
    limpiar_respuestas,
    findall(P, personaje(P, _), Lista),
    buscar(Lista).

buscar([Personaje]) :-
    write('El personaje es: '),
    write(Personaje), nl.

buscar([]) :-
    write('No pude identificar al personaje.'), nl.

buscar(Lista) :-
    obtener_caracteristica_util(Lista, C),
    preguntar(C),
    filtrar_personajes(Lista, C, NuevaLista),
    buscar(NuevaLista).

obtener_caracteristica_util(Lista, C) :-
    member(P, Lista),
    personaje(P, Caracteristicas),
    member(C, Caracteristicas),
    not(respuesta(C,_)),
    sirve_para_dividir(Lista, C),
    !.

sirve_para_dividir(Lista, C) :-
    aparece_en_algunos(Lista, C),
    no_aparece_en_algunos(Lista, C).

aparece_en_algunos(Lista, C) :-
    member(P, Lista),
    personaje(P, L),
    member(C, L), !.

no_aparece_en_algunos(Lista, C) :-
    member(P, Lista),
    personaje(P, L),
    not(member(C, L)), !.

preguntar(C) :-
    (nombre_amigable(C, Frase) -> true ; Frase = C),
    nl, write('¿El personaje '),
    write(Frase),
    write('? (si/no): '),
    read(R),
    assert(respuesta(C,R)).

filtrar_personajes([], _, []).

filtrar_personajes([P|R], C, [P|R2]) :-
    respuesta(C, si),
    personaje(P, Lista),
    member(C, Lista),
    filtrar_personajes(R, C, R2).

filtrar_personajes([P|R], C, [P|R2]) :-
    respuesta(C, no),
    personaje(P, Lista),
    not(member(C, Lista)),
    filtrar_personajes(R, C, R2).

filtrar_personajes([_|R], C, R2) :-
    filtrar_personajes(R, C, R2).

limpiar_respuestas :-
    retract(respuesta(_, _)),
    fail.

limpiar_respuestas.